/// [ExecutionEnv] decorator that injects session-correlation env vars
/// (`FAH_SESSION_ID`, `FAH_SESSION_FILE`, `FAH_PROVIDER`, `FAH_MODEL`) into
/// shell executions.
///
/// Wraps any [ExecutionEnv] and merges the vars from a live [vars] provider
/// into [ShellExecOptions.env] on every [exec], so scripts can correlate
/// their output with the running agent session (pi's bash tool does the
/// same with `PI_SESSION_*`). The provider is consulted per call, so a
/// session created or a model switched after wiring is picked up
/// immediately.
///
/// The vars are never secrets: ids, paths, provider kinds, and model ids
/// only. Compose with `SecretsExecutionEnv` for the full flow; the var
/// names use the reserved `FAH_` prefix and never collide with secret
/// names.
library;

import 'dart:async';
import 'dart:typed_data';

import 'execution_env.dart';

/// Env var name carrying the current session id.
const sessionIdEnvVar = 'FAH_SESSION_ID';

/// Env var name carrying the current session's JSONL file path.
const sessionFileEnvVar = 'FAH_SESSION_FILE';

/// Env var name carrying the active provider kind.
const providerEnvVar = 'FAH_PROVIDER';

/// Env var name carrying the active model id.
const modelEnvVar = 'FAH_MODEL';

/// An [ExecutionEnv] that injects session-correlation env vars into every
/// [exec]. See the library doc for the contract.
final class SessionVarsExecutionEnv
    implements
        ExecutionEnv,
        BackgroundShell,
        RangedReadFileSystem,
        RenamableFileSystem {
  /// Creates a decorator over [delegate] injecting the vars returned by
  /// [vars] (consulted live on every [exec]).
  SessionVarsExecutionEnv(this._delegate, this._vars);

  final ExecutionEnv _delegate;
  final FutureOr<Map<String, String>> Function() _vars;

  /// The wrapped environment.
  ExecutionEnv get delegate => _delegate;

  @override
  String get cwd => _delegate.cwd;

  @override
  Future<Result<ShellExecResult, ExecutionError>> exec(
    String command, {
    ShellExecOptions? options,
  }) async {
    final vars = await _vars();
    if (vars.isEmpty) return _delegate.exec(command, options: options);
    // Per-call env entries win over the injected session vars.
    final merged = ShellExecOptions(
      cwd: options?.cwd,
      env: {...vars, ...?options?.env},
      timeout: options?.timeout,
      cancelToken: options?.cancelToken,
      onStdout: options?.onStdout,
      onStderr: options?.onStderr,
      // stdinData + liveStdin (issue #367): the live stdin channel keeps
      // the pipe open so a mid-run password ask can be answered; the
      // launch-time stdin param rides the same merge.
      stdinData: options?.stdinData,
      liveStdin: options?.liveStdin,
    );
    return _delegate.exec(command, options: merged);
  }

  @override
  bool get backgroundJobsSupported {
    final delegate = _delegate;
    if (delegate case final BackgroundShell bg) {
      return bg.backgroundJobsSupported;
    }
    return false;
  }

  @override
  Future<Result<ShellJob, ExecutionError>> startShellJob(
    String command, {
    required String id,
    required String logPath,
    ShellExecOptions? options,
  }) async {
    final delegate = _delegate;
    if (delegate is! BackgroundShell) {
      return const Err(
        ExecutionError(
          ExecutionErrorCode.shellUnavailable,
          'background shell jobs are not supported by this shell',
        ),
      );
    }
    final bg = delegate as BackgroundShell;
    final vars = await _vars();
    if (vars.isEmpty) {
      return bg.startShellJob(
        command,
        id: id,
        logPath: logPath,
        options: options,
      );
    }
    // Per-call env entries win over the injected session vars.
    final merged = ShellExecOptions(
      cwd: options?.cwd,
      env: {...vars, ...?options?.env},
      timeout: options?.timeout,
      cancelToken: options?.cancelToken,
      onStdout: options?.onStdout,
      onStderr: options?.onStderr,
      // stdinData + liveStdin (issue #367): see exec above.
      stdinData: options?.stdinData,
      liveStdin: options?.liveStdin,
      jobLogMaxBytes: options?.jobLogMaxBytes,
      onJobLogWarning: options?.onJobLogWarning,
      jobLogRedactor: options?.jobLogRedactor,
    );
    return bg.startShellJob(command, id: id, logPath: logPath, options: merged);
  }

  @override
  Future<Result<String, FileError>> absolutePath(String path) =>
      _delegate.absolutePath(path);

  @override
  Future<Result<String, FileError>> joinPath(List<String> parts) =>
      _delegate.joinPath(parts);

  @override
  Future<Result<String, FileError>> readTextFile(String path) =>
      _delegate.readTextFile(path);

  @override
  Future<Result<Uint8List, FileError>> readBinaryFile(String path) =>
      _delegate.readBinaryFile(path);

  @override
  Future<Result<Uint8List, FileError>> readRange(
    String path,
    int start,
    int end,
  ) {
    final delegate = _delegate;
    if (delegate case final RangedReadFileSystem ranged) {
      return ranged.readRange(path, start, end);
    }
    return Future.value(
      Err(
        FileError(
          FileErrorCode.notSupported,
          'readRange not supported by $_delegate',
          path: path,
        ),
      ),
    );
  }

  @override
  Future<Result<void, FileError>> renamePath(String from, String to) {
    final delegate = _delegate;
    if (delegate case final RenamableFileSystem renamable) {
      return renamable.renamePath(from, to);
    }
    return Future.value(
      Err(
        FileError(
          FileErrorCode.notSupported,
          'renamePath not supported by $_delegate',
          path: from,
        ),
      ),
    );
  }

  @override
  Future<Result<List<String>, FileError>> readTextLines(
    String path, {
    int? maxLines,
  }) => _delegate.readTextLines(path, maxLines: maxLines);

  @override
  Future<Result<void, FileError>> writeBinaryFile(
    String path,
    Uint8List content,
  ) => _delegate.writeBinaryFile(path, content);

  @override
  Future<Result<void, FileError>> writeFile(String path, String content) =>
      _delegate.writeFile(path, content);

  @override
  Future<Result<void, FileError>> appendFile(String path, String content) =>
      _delegate.appendFile(path, content);

  @override
  Future<Result<FileInfo, FileError>> fileInfo(String path) =>
      _delegate.fileInfo(path);

  @override
  Future<Result<List<FileInfo>, FileError>> listDir(String path) =>
      _delegate.listDir(path);

  @override
  Future<Result<bool, FileError>> exists(String path) => _delegate.exists(path);

  @override
  Future<Result<void, FileError>> createDir(
    String path, {
    bool recursive = true,
  }) => _delegate.createDir(path, recursive: recursive);

  @override
  Future<Result<void, FileError>> remove(
    String path, {
    bool recursive = false,
    bool force = false,
  }) => _delegate.remove(path, recursive: recursive, force: force);
}

/// The FinalizeGate contract + TaskLedger (gh-1412): near-miss elimination
/// for unattended runs.
///
/// An unattended agent must stop declaring success on intent and start
/// declaring it on re-verified state. Two named components:
///
/// - **FinalizeGate** — the prompt contract (unattended/bench mode only;
///   `prompts/cli/finalize_gate.md`, rendered by the hosts into the system
///   prompt). Before any final summary the agent re-quotes every explicit
///   requirement as a checklist, verifies each item with a real command
///   against the produced state, and fixes or explicitly reports every
///   unmet item.
/// - **TaskLedger** — the checklist itself as a hidden session record
///   (`task_ledger` custom record, shaped like `model_request_summary`):
///   post-mortems see WHAT was self-checked, the bench summary reports
///   near-miss proximity (items verified / checks passed), and CI can
///   REG-gate the contract's presence.
///
/// The loop parses the `task-ledger` fenced block out of the run's final
/// assistant message ([parseTaskLedger]) and emits [TaskLedgerEvent]
/// (declared in `agent_loop.dart` — the event family is sealed there);
/// hosts persist [taskLedgerRecordType] records and the trajectory
/// snapshot builder folds them.
library;

/// The `custom` record type of the TaskLedger session record.
const String taskLedgerRecordType = 'task_ledger';

/// The fenced-block info string the FinalizeGate contract mandates for the
/// final answer's ledger (`​```task-ledger … `​`` `).
const String taskLedgerFence = 'task-ledger';

/// Per-item verification outcome. `fixed` = failed, then fixed and
/// re-verified — counts as verified (the fix loop is the contract's point).
enum TaskLedgerItemStatus {
  pass,
  fail,
  fixed;

  /// The payload spelling.
  String get jsonName => name;

  /// Tolerant parse: a missing or unrecognized status is [fail] — an
  /// unverified item must never silently count as verified.
  static TaskLedgerItemStatus fromName(Object? name) {
    final token = '$name'.trim().toLowerCase().split(RegExp(r'\s')).first;
    if (token.startsWith('pass')) return pass;
    if (token.startsWith('fix')) return fixed;
    return fail;
  }
}

/// One checklist entry: the verbatim requirement quote plus the real
/// verification command and its expected/actual outcome.
final class TaskLedgerItem {
  /// Creates an item. Fields other than [requirement] default to empty;
  /// [status] defaults to [TaskLedgerItemStatus.fail] (unverified).
  const TaskLedgerItem({
    required this.requirement,
    this.command = '',
    this.expected = '',
    this.actual = '',
    this.status = TaskLedgerItemStatus.fail,
  });

  /// The requirement, quoted verbatim from the task text.
  final String requirement;

  /// The command that verified the item against produced state.
  final String command;

  /// What the command should show.
  final String expected;

  /// What it actually showed.
  final String actual;

  /// The outcome.
  final TaskLedgerItemStatus status;

  /// Whether the item counts as verified (`pass` or `fixed`).
  bool get verified => status != TaskLedgerItemStatus.fail;

  /// Serializes for the `task_ledger` session record.
  Map<String, dynamic> toJson() => {
    'requirement': requirement,
    'command': command,
    'expected': expected,
    'actual': actual,
    'status': status.jsonName,
  };

  /// Tolerant parse (forward-versioned payloads): rows without a
  /// requirement are dropped, unknown fields ignored.
  static TaskLedgerItem? fromJson(Object? json) {
    if (json is! Map) return null;
    final requirement = '${json['requirement'] ?? ''}'.trim();
    if (requirement.isEmpty) return null;
    return TaskLedgerItem(
      requirement: requirement,
      command: '${json['command'] ?? ''}',
      expected: '${json['expected'] ?? ''}',
      actual: '${json['actual'] ?? ''}',
      status: TaskLedgerItemStatus.fromName(json['status']),
    );
  }
}

/// The parsed task ledger: the checklist a run finished with.
final class TaskLedger {
  /// Creates a ledger.
  const TaskLedger({required this.items});

  /// One entry per checklist requirement.
  final List<TaskLedgerItem> items;

  /// Items verified against produced state (`pass` + `fixed`).
  int get verifiedCount => items.where((item) => item.verified).length;

  /// Items still unmet.
  int get failedCount => items.length - verifiedCount;

  /// Whether every item verified — the gate's green state.
  bool get allVerified => failedCount == 0 && items.isNotEmpty;

  /// Serializes for the `task_ledger` session record.
  Map<String, dynamic> toJson() => {
    'items': [for (final item in items) item.toJson()],
  };

  /// Tolerant parse: non-map payloads and requirement-less rows never
  /// throw; a payload with no surviving items parses to null.
  static TaskLedger? fromJson(Object? json) {
    if (json is! Map) return null;
    final raw = json['items'];
    if (raw is! List) return null;
    final items = [for (final row in raw) ?TaskLedgerItem.fromJson(row)];
    if (items.isEmpty) return null;
    return TaskLedger(items: items);
  }
}

final RegExp _fenceLine = RegExp(r'^\s*(`{3,})(.*)$');

/// Parses the LAST `task-ledger` fenced block out of [text] — the shape the
/// FinalizeGate contract mandates for the final answer. Returns null when
/// the text carries no block (legacy answers replay unchanged) or the block
/// holds no requirement-bearing entries.
///
/// Entries are `- key: value` lines; further `key: value` lines (deeper
/// indented) extend the current entry. Missing statuses parse as
/// [TaskLedgerItemStatus.fail]; unknown keys are ignored.
TaskLedger? parseTaskLedger(String text) {
  final block = _lastLedgerBlock(text);
  if (block == null) return null;
  final items = <TaskLedgerItem>[];
  Map<String, String> current = {};
  void flush() {
    final requirement = (current['requirement'] ?? '').trim();
    if (requirement.isNotEmpty) {
      items.add(
        TaskLedgerItem(
          requirement: requirement,
          command: current['command'] ?? '',
          expected: current['expected'] ?? '',
          actual: current['actual'] ?? '',
          status: TaskLedgerItemStatus.fromName(current['status']),
        ),
      );
    }
    current = {};
  }

  for (final line in block.split('\n')) {
    final entry = RegExp(r'^\s*-\s+([A-Za-z_]+)\s*:\s?(.*)$').firstMatch(line);
    final field = RegExp(r'^\s+([A-Za-z_]+)\s*:\s?(.*)$').firstMatch(line);
    if (entry != null) {
      flush();
      current[entry.group(1)!] = entry.group(2) ?? '';
    } else if (field != null && current.isNotEmpty) {
      current[field.group(1)!] = field.group(2) ?? '';
    }
  }
  flush();
  if (items.isEmpty) return null;
  return TaskLedger(items: items);
}

/// The body of the last ` ```task-ledger ` fenced block in [text], or null.
String? _lastLedgerBlock(String text) {
  String? last;
  var inside = false;
  for (final line in text.split('\n')) {
    final match = _fenceLine.firstMatch(line);
    if (match == null) {
      if (inside) last = '${last ?? ''}$line\n';
      continue;
    }
    final info = match.group(2)!.trim();
    if (inside) {
      inside = false; // Closing fence — the block is complete.
    } else if (info == taskLedgerFence) {
      inside = true;
      last = null;
    }
  }
  return last?.trimRight();
}

/// Renders [ledger] back into the fenced `task-ledger` block the contract
/// mandates (the parser's exact input shape) — the IT harness and tests
/// build final answers with it.
String formatTaskLedgerBlock(TaskLedger ledger) {
  final buffer = StringBuffer('```task-ledger\n');
  for (final item in ledger.items) {
    buffer
      ..writeln('- requirement: ${item.requirement}')
      ..writeln('  command: ${item.command}')
      ..writeln('  expected: ${item.expected}')
      ..writeln('  actual: ${item.actual}')
      ..writeln('  status: ${item.status.jsonName}');
  }
  buffer.write('```');
  return buffer.toString();
}

part of 'agent_cli.dart';

// Implementation members of [AgentCli] for the agent messaging fabric and
// the idle inbox-wake loop — split out of `agent_cli.dart` to keep it under
// the repo's 2800-line size gate. Same library (a `part of`), so the
// extension sees the class's private fields (`_subagentManager`,
// `_session`, the wake-guard fields in the main file) with no visibility
// change.
/// Ceiling for one plugin-inbox drain: a wedged hub RPC must never hold
/// the run's settle hostage.
const Duration _hubDrainTimeout = Duration(seconds: 5);

extension AgentCliMessagingFlow on AgentCli {
  /// The main agent's inbox as steering messages: each pending fabric
  /// message becomes a user message attributed to its sender, so the
  /// transcript reads like a chat between agents. A `user`-kind message
  /// (an attached client — the Fa app's attach view — handing over user
  /// input) lands as the user's own words with a dim attribution prefix,
  /// not an agent chat line.
  Future<List<Message>> _mainInboxMessages() async {
    final queued = await _subagentManager.drainMessages(
      _subagentManager.selfId,
    );
    // A delivered `user`-kind message IS real user input: it resets the
    // inbox-wake streak exactly like a typed line would. Without this, an
    // attach-driven workflow (terminal open, every message sent from the
    // app) burns the 10-run agent-chat cap and the CLI goes permanently
    // silent on further app mail until restart.
    if (queued.any((message) => message.isUserInput)) {
      _inboxWakePolicy.resetStreak();
    }
    // The btw panels: each drained fabric message lands as a bordered
    // panel block at delivery time (issue #277).
    _hubPanelsForInbox(queued);
    final messages = [
      for (final message in queued)
        _steeringLine(
          message.fromId,
          message.text,
          userInput: message.isUserInput,
        ),
    ];
    // Plugin inboxes (e.g. the hub) join the same steering flow, after
    // the fabric mail. A source that throws is skipped — the steering
    // contract is that this closure never throws.
    for (final inbox in _pluginInboxes) {
      final List<AgentMessage> drained;
      try {
        // ponytail: a timed-out drain loses any batch still in flight;
        // retain-future retry only if mail loss on a wedged hub ever
        // matters more than run liveness.
        drained = await inbox.drain().timeout(
          _hubDrainTimeout,
          onTimeout: () {
            io.writeln(
              _style.dim('[mail] hub drain timeout — skipping this poll'),
            );
            return <AgentMessage>[];
          },
        );
      } on Object {
        continue;
      }
      if (drained.any((message) => message.kind == AgentMessageKind.user)) {
        _inboxWakePolicy.resetStreak();
      }
      messages.addAll([
        for (final message in drained)
          _steeringLine(
            message.fromId,
            message.text,
            userInput: message.kind == AgentMessageKind.user,
          ),
      ]);
    }
    return messages;
  }

  /// Sender-attributed steering line for one inbox message: user input
  /// (an attached client handing over the user's words) lands with an
  /// attribution prefix; agent chat reads as a chat line.
  Message _steeringLine(
    String fromId,
    String text, {
    required bool userInput,
  }) => userInput
      ? UserMessage.text('[from $fromId] ${text.trim()}')
      : UserMessage.text('from $fromId: ${text.trim()}');

  /// The steering probe: fabric mail pending, or any plugin inbox
  /// reports unread mail. Never throws — a broken plugin probe counts
  /// as empty.
  Future<bool> _mainInboxProbe() async {
    final count = await _subagentManager.pendingInboxCount(
      _subagentManager.selfId,
    );
    if (count > 0) return true;
    return _anyPluginInboxPending();
  }

  /// Non-draining check across every registered plugin inbox; a probe
  /// that throws counts as empty.
  Future<bool> _anyPluginInboxPending() async {
    for (final inbox in _pluginInboxes) {
      final hasPending = inbox.hasPending;
      if (hasPending == null) continue;
      try {
        if (await hasPending()) return true;
      } on Object {
        // Broken probe — the drain still guards itself.
      }
    }
    return false;
  }

  /// The scheduled-records root resolved LIVE from the current env cwd:
  /// `_messagesRoot` pins the launch cwd (the fabric mailboxes stay there),
  /// but session-folder adoption (`_loadSession` repoints `_env.cwd`) must
  /// move the pending queue with it — a pinned root lands records where the
  /// post-adoption sweeps never look (issue #59).
  String get _scheduledMessagesRoot =>
      '${config.sessionRoot}/${encodeSessionCwd(_env.cwd)}/messages';

  /// The mailbox of the subagent whose run encloses the caller, or null on
  /// the main agent (gh-970). `schedule_message` resolves "your own
  /// mailbox" through this — the queue's `selfMailbox` always names MAIN,
  /// so without it every child self-reminder landed in main's inbox.
  String? _childSenderMailbox() {
    final id = activeSubagentId();
    return id == null ? null : _subagentManager.mailboxOf(id);
  }

  /// Namespaces this instance's mailboxes with the active session id: two
  /// Fa instances sharing the messaging root never drain each other's
  /// inboxes. Called after every session init/switch.
  /// The wake-receipt trail (gh-1180 AC4) built alongside the queue: the
  /// non-nullable log the idle-wake path writes its wake_attempted /
  /// turn_started / wake_refused events through. A `late final` so the
  /// production wake path can never silently skip the trail because a
  /// lazy initializer has not run yet (review T11).
  ScheduledReceiptLog _newScheduledReceipts() => ScheduledReceiptLog(
    env: _env,
    path: () => '$_scheduledMessagesRoot/_scheduled/receipts.jsonl',
    onError: (text) => io.writeln('[sched] $text'),
  );

  ScheduledMessageQueue _newScheduledMessages() {
    return ScheduledMessageQueue(
      env: _env,
      repo: () => _fabricRepository,
      root: () => _scheduledMessagesRoot,
      selfMailbox: () => _subagentManager.mailboxOf('main'),
      // Ownership tag for schedule records: a sweeper re-addresses a
      // self-addressed record only when the stored prefix matches this
      // session — another instance's record stays with its owner (#59).
      ownerPrefix: () => _subagentManager.mailboxPrefix,
      // gh-1180 AC4: the persisted receipt trail — scheduled / delivered /
      // delivery_failed / scan_failed events keyed by record id, so a
      // post-mortem can tell "timer never fired" from "wake refused".
      // Rides the non-nullable [_scheduledReceipts] the wake path also
      // writes through (one log, one trail — review T11).
      receipts: _scheduledReceipts,
      // Terminal visibility: a dim line when a scheduled message is created
      // and when it fires, so self-reminders are observable without /tasks.
      // Each transition also re-pushes the TUI indicator row (issue #115).
      onScheduled: (text) {
        io.writeln(_style.dim('[sched] $text'));
        unawaited(_pushScheduledStatus());
      },
      onFired: (text) {
        io.writeln(_style.dim('[sched] $text'));
        _hubAddPanel(
          kind: DeferredPanelKind.scheduled,
          from: 'scheduler',
          body: text,
          source: '/schedule',
        );
        unawaited(_pushScheduledStatus());
      },
      // Failure isolation (issue #270): a failed delivery is a visible
      // [sched] line, never a dead heartbeat — the record stays for the
      // next sweep.
      onError: (text) {
        io.writeln('[sched] $text');
      },
    );
  }

  /// The prompt-affecting half of [_syncMailboxPrefix]: assigns the
  /// mailbox prefix and recomposes (the messaging section rides the
  /// prompt). Split out so the resume budget can project the section
  /// BEFORE the gh-968 parity walk (`_loadSession`, issue #1151 review)
  /// without the prefix assignment drifting between the two sites.
  void _assignMailboxPrefix(String id) {
    _subagentManager.mailboxPrefix = id;
    _applyPromptComposition();
  }

  void _syncMailboxPrefix() {
    _assignMailboxPrefix(_session?.cachedId ?? '');
    // Issue #426: child session headers carry `metadata.parent` from the
    // manager's parentSessionId — pinned empty at construction because
    // the session id does not exist yet. Assign it here (the moment the
    // id materializes) so children of THIS session link back to it
    // instead of being written with `parent: ""`.
    _subagentManager.parentSessionId = _subagentManager.mailboxPrefix;
    // Re-arm scheduled-message delivery: pending records that came due
    // while another session was active surface in the now-active mailbox
    // (start() is an idempotent re-arm + drain).
    unawaited(_scheduledMessages.start());
    unawaited(_pushScheduledStatus());
    // Presence: a zero-mail instance is discoverable in agent_directory.
    // The session display name rides along so peers can address this
    // mailbox by name (`--session goal_builder` → `goal_builder/main`).
    final fabric = _subagentManager.messaging;
    final prefix = _subagentManager.mailboxPrefix;
    if (fabric != null && prefix.isNotEmpty) {
      unawaited(_registerFabricMailbox(fabric, prefix));
    }
  }

  /// Re-reads the pending scheduled records and pushes the count + nearest
  /// due into the TUI indicator row (issue #115). Best-effort: a failing
  /// scan only means a stale indicator, never a broken flow.
  Future<void> _pushScheduledStatus() async {
    try {
      final pending = await _scheduledMessages.pendingSummary();
      _tuiController?.setScheduled(pending.count, pending.nextDueMs);
    } on Object {
      // Indicator only — never let visibility break messaging.
    }
  }

  /// Registers the main mailbox with its session display name (best-effort:
  /// a failure never blocks the session switch).
  Future<void> _registerFabricMailbox(
    MessagingRepository fabric,
    String prefix,
  ) async {
    final name = await _session?.getSessionName();
    final trimmed = name?.trim();
    await fabric.register(
      _subagentManager.mailboxOf(_subagentManager.selfId),
      sessionName: (trimmed == null || trimmed.isEmpty) ? null : trimmed,
      capabilities: config.agentCapabilities,
    );
  }

  /// Best-effort fabric heartbeat: refreshes this instance's mailbox
  /// liveness marker so agent_directory reports it as live between mails.
  void _touchFabricHeartbeat() {
    final fabric = _subagentManager.messaging;
    if (fabric == null) return;
    unawaited(
      fabric.touch(
        _subagentManager.mailboxOf(_subagentManager.selfId),
        // Mid-run the agent is busy: a directory mark distinct from the
        // idle live heartbeat (issue #27 phase 2).
        busy: isBusy,
      ),
    );
  }

  /// The inbox watcher tick: while IDLE, new inter-agent mail starts a turn
  /// (the loop's first steering poll drains the inbox into the run). Mid-run
  /// mail needs no wake — the per-turn steering poll already delivers it.
  Future<void> _wakeOnInboxMail() async {
    if (_exited || isBusy || _inboxWakeRunning) return;
    // The lane decision (gh-1180): user-kind mail always wakes (gating it
    // on the streak would deadlock: no run → no reset → no run);
    // delivered scheduled self-mail is EXEMPT from the cap (a deliberate
    // agent-chosen cadence — the night-watch lane); foreign agent-to-agent
    // chatter stays capped (anti-storm).
    final pending = await _subagentManager.pendingInbox(
      _subagentManager.selfId,
    );
    final pluginPending = await _anyPluginInboxPending();
    if (pending.isEmpty && !pluginPending) return;
    final decision = _inboxWakePolicy.wakeDecisionFor(
      pending,
      pluginPending: pluginPending,
    );
    if (!decision.wake) {
      // gh-1180 AC4: the refusal is receipted AND visible — a silent
      // drop here was exactly the 2h04m blind window. Both receipts ride
      // the policy's once-per-EPISODE gate (review T1): the gate holds
      // until user input arrives, so per-tick appends would grow
      // receipts.jsonl by ~43k duplicate lines/day. The episode latch
      // lives in the policy next to the streak (review T2) and re-arms
      // on the same resets — a user input or an allowed non-exempt
      // wake — so a repeat episode is announced and receipted again.
      if (_inboxWakePolicy.announceRefusal()) {
        io.writeln(
          _style.dim('[mail] wake refused — ${decision.refusalReason}'),
        );
        await _scheduledReceipts.append('wake_attempted', {
          'lane': decision.lane.name,
          'ids': [for (final message in pending) message.id],
        });
        await _scheduledReceipts.append('wake_refused', {
          'lane': decision.lane.name,
          'reason': decision.refusalReason,
        });
      }
      return;
    }
    // The policy books cap-consuming wakes itself (its streak is the one
    // source of truth; the legacy seam proxies it).
    _inboxWakeRunning = true;
    final count = pending.length;
    io.writeln(
      _style.dim(
        count > 0
            ? '[mail] $count new message(s) — waking up to answer'
            : '[mail] new hub message(s) — waking up to answer',
      ),
    );
    await _scheduledReceipts.append('wake_attempted', {
      'lane': decision.lane.name,
      'ids': [for (final message in pending) message.id],
    });
    await _scheduledReceipts.append('turn_started', {
      'lane': decision.lane.name,
      'ids': [for (final message in pending) message.id],
    });
    _startRun(
      '<system-notice>New inter-agent mail arrived '
      '${count > 0 ? '($count message(s))' : '(hub mail)'} — the messages '
      'follow below as user messages. Read them and act: reply via the '
      "sender's messaging tool (agent_message for fabric addresses, dap_dm "
      'for hub peers) when a response is expected, or just incorporate the '
      'information.</system-notice>',
    );
    unawaited(_settled.whenComplete(() => _inboxWakeRunning = false));
  }

  /// Receive-side healing: a sender running an older binary (or any tool
  /// scripting the fabric directly) can address this agent with a truncated
  /// id — the send lands in a fresh mailbox directory no watcher polls and
  /// the message is silently lost. Sweep orphan mailboxes into the real
  /// inbox before the drain so the mail is never lost. Best-effort; runs on
  /// the file-backed local root only (this host's messages root).
  Future<void> _reclaimOrphanFabricMail() async {
    try {
      await reclaimOrphanMailboxMail(
        env: _env,
        root: _messagesRoot,
        agentId: _subagentManager.mailboxOf(_subagentManager.selfId),
      );
      // Catch-up sweep: records scheduled by a previous process (or a
      // sibling pane that exited) come due with nobody armed for them —
      // deliver here so the reminder still surfaces (issue #59).
      await _scheduledMessages.deliverDue();
    } on Object {
      // Never let fabric hygiene break the watcher tick.
    }
  }
}

/// Builds the detached wake command for an asleep mailbox:
/// `nohup <exe> --session <name> "<prompt>" >/dev/null 2>&1 &`. Single
/// quotes every shell word; falls back to `fa` on PATH when [wakeExecutable]
/// is null/empty and to [sessionId] when [sessionName] is.
String mailboxWakeCommand({
  String? wakeExecutable,
  required String sessionId,
  String? sessionName,
}) {
  final exe = (wakeExecutable == null || wakeExecutable.isEmpty)
      ? 'fa'
      : wakeExecutable;
  final address = (sessionName == null || sessionName.isEmpty)
      ? sessionId
      : sessionName;
  String q(String s) => "'${s.replaceAll("'", r"'\''")}'";
  return 'nohup ${q(exe)} --session ${q(address)} '
      '${q(wakePromptText)} >/dev/null 2>&1 & echo woken';
}

