/// Applies the request-payload rewrites before a provider call: the
/// `transformContext` hook and the symmetric tool-pairing repair. Only the
/// request payload is rewritten, never the transcript. Returns the payload
/// plus what the pairing repair changed (empty when nothing did).
Future<(Context, ToolPairingRepairReport)> _buildRequestContext(
  Context context,
  AgentLoopConfig config,
  CancelToken? cancelToken, {
  String? misuseNote,
}) async {
  // pi applies transformContext (then convertToLlm) before each provider
  // call; only the request payload is rewritten, never the transcript.
  var requestContext = context;
  final transformContext = config.transformContext;
  if (transformContext != null) {
    requestContext = Context(
      systemPrompt: context.systemPrompt,
      messages: await transformContext(List.of(context.messages), cancelToken),
      tools: context.tools,
    );
  }
  // Session image registry (#171): unique history images ride once as
  // `[Image N]` carriers; every other occurrence becomes a text ref.
  // Payload-only rewrite — the transcript is never touched, and the
  // kill switch (`images.registry: false`) skips it entirely.
  if (imageRegistryConfig.enabled) {
    final rewritten = rewriteHistoryImages(
      requestContext.messages,
      onDrop: imageDropNotice,
    );
    if (!identical(rewritten, requestContext.messages)) {
      requestContext = Context(
        systemPrompt: requestContext.systemPrompt,
        messages: rewritten,
        tools: requestContext.tools,
      );
    }
  }
  // gh-1409: compaction-pinned skill operative lines ride every
  // post-boundary request as the verbatim carrier (AC2) — payload-only,
  // the transcript is never touched; the kill switch
  // (`operativePinConfig.enabled = false`) skips it entirely. Runs BEFORE
  // tool-pairing repair: the carrier is a standalone user message and can
  // never break a call/result run (it anchors outside them).
  if (config.operativeSkills.isNotEmpty && operativePinConfig.enabled) {
    // E9: the pin budget shrinks proportionally on tiny windows so pins
    // never crowd out the recent-token working set — an eighth of the
    // effective window, floored at 1024 chars (one 512-char line plus
    // envelope), capped at the configured budget.
    final window = effectiveContextWindow(
      config.model.contextWindow,
      config.contextWindowCap,
    );
    final budgetChars = min(
      operativePinConfig.budgetChars ?? defaultPinBudgetChars,
      // E9: at most an eighth of the effective window, floored at 1024
      // chars (one 512-char line plus envelope) — a large window keeps the
      // full default budget, a tiny one shrinks the pins proportionally.
      max(window ~/ 8, 1024),
    );
    final injected = injectOperativePinCarriers(
      requestContext.messages,
      skills: config.operativeSkills,
      budgetChars: budgetChars,
      onNotice: operativePinNotice,
    );
    if (!identical(injected, requestContext.messages)) {
      requestContext = Context(
        systemPrompt: requestContext.systemPrompt,
        messages: injected,
        tools: requestContext.tools,
      );
    }
  }
  // Broken tool pairing (orphan results at any position, displaced results,
  // duplicate ids, unanswered calls) makes providers hard-400 EVERY
  // subsequent request; repair the payload, never the transcript.
  // gh-1449: the session's reported-orphan latch rides the repair — an
  // orphan is noted once, then dropped silently; the new keys merge back
  // into the owner set so the next request (and the pairing-heal retry)
  // sees them.
  final repaired = repairToolPairing(
    requestContext.messages,
    reportedOrphanKeys: config.reportedOrphanKeys ?? const <String>{},
  );
  if (repaired.report.notedOrphanKeys.isNotEmpty) {
    config.reportedOrphanKeys?.addAll(repaired.report.notedOrphanKeys);
  }
  if (!identical(repaired.messages, requestContext.messages)) {
    requestContext = Context(
      systemPrompt: requestContext.systemPrompt,
      messages: repaired.messages,
      tools: requestContext.tools,
    );
  }
  // Issue #862: an armed corrective note rides the NEXT request payload as
  // a trailing user message — visible to the model, never in the transcript.
  // Drained ONCE by the caller ([_streamAssistantResponse], before the
  // attempt loop) and re-attached on every rebuild, so an over-window
  // retry cannot silently drop an already-armed note (issue #862 review).
  if (misuseNote != null) {
    requestContext = Context(
      systemPrompt: requestContext.systemPrompt,
      messages: [...requestContext.messages, UserMessage.text(misuseNote)],
      tools: requestContext.tools,
    );
  }
  return (requestContext, repaired.report);
}

/// Builds the outbound-request capture emitted with [ModelRequestEvent]
/// (issue #385): the cheap summary (message count/sizes, tool names,
