  final Set<DeadlineNoticeKind> _fired = <DeadlineNoticeKind>{};

  bool get isArmed => _deadlineEpochMs != null;
  int? get deadlineEpochMs => _deadlineEpochMs;
  int? get armedAtEpochMs => isArmed ? _armedAtEpochMs : null;

  int get _nowMs => _clock().millisecondsSinceEpoch;

  /// ms remaining; throws StateError when unarmed.
  int get remainingMs {
    final deadline = _deadlineEpochMs;
    if (deadline == null) throw StateError('no deadline armed');
    return deadline - _nowMs;
  }

  void setDuration(Duration budget) { ... epoch = now + budget.inMilliseconds; }
  void setEpochMs(int epochMs) {
    if (epochMs <= _nowMs) throw FormatException('deadline is in the past');
    _deadlineEpochMs = epochMs;
    _armedAtEpochMs = _nowMs;
    _fired.clear();
  }
  void setFromSpec(String spec) {
    final parsed = parseDeadlineSpec(spec);
    if (parsed.epochMs != null) { setEpochMs(parsed.epochMs!); } else { setDuration(parsed.duration!); }
  }
  void clear() { _deadlineEpochMs = null; _fired.clear(); _armedAtEpochMs = 0; }

  /// 'time-left: 5min' or null when unarmed.
  String? budgetLine() {
    if (!isArmed) return null;
    return 'time-left: ${formatTimeLeft(remainingMs)}';
  }

  /// One-shot crossing notices...
  List<DeadlineNotice> pollNotices() {
    if (!isArmed) return const [];
    final deadline = _deadlineEpochMs!;
    final remaining = deadline - _nowMs;
    final total = deadline - _armedAtEpochMs;
    final out = <DeadlineNotice>[];
    void fire(DeadlineNoticeKind kind, bool crossed) {
      if (crossed && _fired.add(kind)) {
        out.add(DeadlineNotice(kind, _ladder.text(kind, formatTimeLeft(remaining))));
